  function Vector2(x: number, y: number): Vector2;
  // ── extension: collection-extensions ──
  interface OrderedArray<T> extends Array<T> {
    ThenBy<TKey>(selector: (value: T) => TKey): OrderedArray<T>;
    ThenByDescending<TKey>(selector: (value: T) => TKey): OrderedArray<T>;
  }

  interface Array<T> {
    Any(predicate?: (value: T) => boolean): boolean;
    All(predicate: (value: T) => boolean): boolean;
    Where(predicate: (value: T) => boolean): T[];
    Select<TResult>(selector: (value: T, index: number) => TResult): TResult[];
    SelectMany<TResult>(selector: (value: T, index: number) => TResult[]): TResult[];
    First(predicate?: (value: T) => boolean): T;
    FirstOrDefault(predicate?: (value: T) => boolean): T | null;
    Last(predicate?: (value: T) => boolean): T;
    LastOrDefault(predicate?: (value: T) => boolean): T | null;
    Single(predicate?: (value: T) => boolean): T;
    SingleOrDefault(predicate?: (value: T) => boolean): T | null;
    Sum(selector?: (value: T) => number): number;
    Min(selector?: (value: T) => number): number;
    Max(selector?: (value: T) => number): number;
    Average(selector?: (value: T) => number): number;
    OrderBy<TKey>(selector: (value: T) => TKey): OrderedArray<T>;
    OrderByDescending<TKey>(selector: (value: T) => TKey): OrderedArray<T>;
    Take(count: number): T[];
    Skip(count: number): T[];
    Distinct(): T[];
    DistinctBy<TKey>(selector: (value: T) => TKey): T[];
    GroupBy<TKey>(selector: (value: T) => TKey): Array<T[] & { Key: TKey }>;
    GroupBy<TKey, TElement>(selector: (value: T) => TKey, elementSelector: (value: T) => TElement): Array<TElement[] & { Key: TKey }>;
    Aggregate(accumulator: (accumulator: T, value: T) => T): T;
    Aggregate<TAccumulator>(seed: TAccumulator, accumulator: (accumulator: TAccumulator, value: T) => TAccumulator): TAccumulator;
    Reverse(): T[];
    Concat(other: T[]): T[];
    Contains(value: T): boolean;
    ToList(): T[];
    ToArray(): T[];
    Count(predicate?: (value: T) => boolean): number;
  }

  interface ActorInfo {
    Action?: string | null;
    Animation?: string | null;
    CurrentAnimationId: number;
    CurrentAnimationStage: number;
    AnimationProgress: number;
  }

  enum AilmentKind {
    Bleeding = "Bleeding",
    BleedingOrCorruption = "BleedingOrCorruption",
    Burning = "Burning",
    Chilled = "Chilled",
    Corruption = "Corruption",
    Cursed = "Cursed",
    Exposed = "Exposed",
    Frozen = "Frozen",
    FrozenOrChilled = "FrozenOrChilled",
    Poisoned = "Poisoned",
    Shocked = "Shocked",
    UnableToRecover = "UnableToRecover",
  }

  /**
   * A resolved native ascendancy. Id is stable; Name is localized.
   */
  interface AscendancyInfo {
    /**
     * Stable native ascendancy identifier.
     * Compare with Ascendancy constants instead of the display name.
     * @keywords character, ascendancy, identifier, condition
     */
    readonly Id: string;
    /**
     * Localized ascendancy display name.
     * Use Id for conditions that should not depend on display text.
     * @keywords character, ascendancy, display, name
     */
    readonly Name: string;
  }

  /**
   * A resolved native character class. Id is the stable metadata ID; Name is localized.
   */
  interface CharacterClassInfo {
    /**
     * Null means the character is known to have no ascendancy selected.
     * @keywords character, ascendancy, specialization, selection
     */
    readonly Ascendancy?: AscendancyInfo | null;
    /**
     * Stable native metadata identifier.
     * Compare with CharacterClass constants instead of the display name.
     * @keywords character, class, identifier, condition
     */
    readonly Id: string;
    /**
     * Localized class display name.
     * Separate from the player's chosen PlayerName; use Id for conditions.
     * @keywords character, class, display, name
     */
    readonly Name: string;
  }

  interface Color {
    R: number;
    G: number;
    B: number;
    A: number;
  }

  /**
   * Presentation of an NPC dialog option, not quest state or click eligibility.
   * In particular Dimmed does not claim Disabled, and Quest can mean accept OR reward.
   */
  enum DialogTextType {
    Quest = "Quest",
    Normal = "Normal",
    Dimmed = "Dimmed",
    Exit = "Exit",
    Unknown = "Unknown",
  }

