  /**
   * Typed data delivered to an `OnNetworkMessage(...).If(...).Do(...)` rule.
   * @keywords network, message, payload, sender
   */
  interface NetworkMessage {
    /**
     * Channel attached to the received message.
     * @keywords network, channel, routing
     */
    Channel: string;
    /**
     * User name attached to the received message.
     * @keywords network, sender, username
     */
    Sender: string;
    /**
     * Received message payload as text; interpret its format in the callback.
     * @keywords network, payload, content, text
     */
    Content: string;
    /**
     * Message timestamp expressed as milliseconds since the Unix epoch.
     * @keywords network, timestamp, unix, milliseconds
     */
    TimestampUnixMs: number;
  }

  /**
   * Configure a network-message rule whose predicate and action receive a `NetworkMessage`.
   * Fluent methods update and return the same builder; attach `.Do(...)` to handle messages.
   * @keywords network, message, rules, builder, callback
   */
  interface NetworkMessageRuleBuilderContext {
    /**
     * Handle a message only when its predicate returns true; replaces any earlier predicate.
     * @keywords network, predicate, condition, filter
     */
    If(predicate: (networkmessage: NetworkMessage) => boolean): this;
    /**
     * Limit action frequency; messages arriving during cooldown are skipped, not delayed for later.
     * @param cooldown_ms Minimum milliseconds between fires; non-positive or non-finite values disable it.
     * @keywords network, cooldown, throttle, rate limit
     */
    Cooldown(cooldown_ms: number): this;
    /**
     * Bind the rule to an existing group handle or a group name.
     * A disabled group suppresses message handling.
     * @keywords network, groups, enable, disable
     */
    Group(group: GroupScope | string): this;
    /**
     * Set the callback for matching messages; replaces any earlier action.
     * Sleep and returned Promises suppress new deliveries until completion; rule context survives waits.
     * Stop abandons automation-owned continuations without JS finally; the host releases held input.
     * A rule without Do handles nothing.
     * @keywords network, message, action, callback
     */
    Do(action: (networkmessage: NetworkMessage) => unknown): this;
  }

  /**
   * Script-facing surface over the PoE2 AI behavior registry — `World.Ai` in scripts.
   *
   * READ-ONLY: writing is the named per-behavior setters' job (`SetAutoFarm`, `SetVoidZoneTracker`,
   * ... on the sandbox root), so there is no generic toggle here. Reads resolve through
   * [`Poe2Game::htn_manager`] into the registry methods on `Poe2HtnManager`, which hold the single
   * exhaustive match per question.
   */
  interface Poe2AiAccessor {
    /**
     * Whether `behavior` is currently enabled — the authoritative registry answer, `false`
     * when detached or the HTN manager is unavailable.
     * Reads the stored toggle, not current execution. Use IsActive to also require the global Automation gate.
     * @example
     * ```ts
     * const followEnabled = World.Ai.IsEnabled(Poe2Behavior.AutoFollow);
     * ```
     * @keywords automation, follow, toggle, enabled, behavior
     */
    IsEnabled(behavior: Poe2Behavior): boolean;
    /**
     * The behavior's live status line (its `Status()` seam), or a short explanation when the
     * game is detached / the manager is unavailable.
     */
    Status(behavior: Poe2Behavior): string;
    /**
     * Whether `behavior` is currently derived-ACTIVE — the authoritative registry answer
     * (`IsActive == IsEnabled AND the global Automation gate is active`), `false` when detached or the HTN manager is
     * unavailable. Distinct from [`Self::IsEnabled`] (the raw stored intent): a behavior can be
     * enabled yet inactive because the global Automation gate is inactive.
     * Active does not mean the character is currently moving or executing a follow task.
     * @keywords automation, follow, active, gate, behavior
     */
    IsActive(behavior: Poe2Behavior): boolean;
    /**
     * The decisive REASON behind `behavior`'s current derived activation ("Automation inactive" when the
     * global Automation gates it off, "<Behavior> off" when its own intent is off, "<Behavior> active"
     * otherwise), or a short explanation when detached / the manager is unavailable. Pairs with
     * [`Self::IsActive`] and complements the behavior's own [`Self::Status`] activity line.
     */
    Reason(behavior: Poe2Behavior): string;
    /**
     * Names of every togglable behavior, straight from the single [`ALL`] table.
     */
    Behaviors: string[];
  }

  interface Poe2AilmentsAccessor {
    /**
     * Whether the ailment is observed; false when buff data is unavailable or inconclusive.
     * @keywords ailments, buffs, condition
     */
    Get(Kind: AilmentKind): boolean;
  }

  interface Poe2AreaAccessor {
    IsValid: boolean;
    /**
     * Resolved `WorldAreas.dat` facts, or `None` when the current row is unavailable.
     */
    Current: Poe2CurrentAreaInfo | null;
    CurrentAreaLevel: number;
    CurrentAreaHash: number;
    LastZoneChangedAtMs: number | null;
    /**
     * Whether the current game session has established a confirmed area identity baseline.
     */
    IsZoneHistoryKnown: boolean;
    EntitiesCount: number;
    /**
     * Entity-tree root pointer as the established JavaScript number projection, or 0 when detached.
     */
    EntityTreeRoot: number;
  }

