  /**
   * Script-facing surface over the global Automation toggle — `World.Automation` in scripts.
   *
   * Unlike [`crate::Poe2AiAccessor::Poe2AiAccessor`], this does not address an
   * individual HTN behavior. `SetEnabled` queues through the script host-command path so it lands
   * on the next game-tick boundary; the runtime dispatcher owns the actual mutation.
   */
  interface Poe2AutomationAccessor {
    /**
     * Whether global Automation is enabled — the live user-toggle intent. This is distinct from
     * derived activity: it can be enabled while the game is detached or its window is backgrounded.
     */
    IsEnabled: boolean;
    /**
     * Set global Automation enabled state. The runtime dispatcher queues this onto the automation
     * manager's control mailbox, so script code never mutates the gate mid-tick.
     */
    SetEnabled(enabled: boolean): void;
  }

  /**
   * One backpack item projected to plain script data (the facade-data equivalent of iterating the C#
   * `Inventory.Backpack` server inventory). Grid position + size come from the server slot; name /
   * corruption come from the item entity's `Base` component. `ItemAddress` is the backing item-entity
   * address, so a script can correlate a backpack item with a ground/entity read.
   */
  interface Poe2BackpackItemInfo {
    /**
     * The live in-game item entity — the real object a script should read, not a snapshot.
     * `ItemAddress` stays as a denormalized convenience scalar for cross-correlation.
     */
    Item?: Entity | null;
    PosX: number;
    PosY: number;
    SizeX: number;
    SizeY: number;
    Name: string;
    IsCorrupted: boolean;
    /**
     * JavaScript numbers retain the established script contract for pointer-like diagnostic values.
     */
    ItemAddress: number;
  }

