  /**
   * Live script-facing wrapper over [`Poe2Game::clock`].
   */
  interface Poe2ClockAccessor {
    /**
     * Game-clock "now", in TICKS (100 ns units — the .NET `TimeSpan`/`Stopwatch` tick, NOT a game
     * frame). Time-base: the managed game clock, which advances once per game REFRESH; it does NOT
     * advance while the script is Automation-gated (Automation off / window background), because a gated refresh
     * still ticks the game clock but the SCRIPT tick — the only place a script observes this value —
     * is skipped, so from the script's perspective the reading is frozen at the last active tick.
     * `0` when the game is detached.
     */
    NowTicks: number;
    /**
     * The most recent frame delta, in TICKS (100 ns units). Time-base: game clock; frozen while
     * Automation-gated (see [`Self::NowTicks`]). `0` when detached.
     */
    DeltaTicks: number;
    /**
     * The tick value captured when the game clock STARTED, in TICKS (100 ns units). Time-base: game
     * clock (a fixed epoch, so it does not move with gating). `0` when detached.
     */
    StartedAtTicks: number;
    /**
     * The ACTUAL wall-clock "now", in TICKS (100 ns units), read straight from the underlying
     * stopwatch — unlike [`Self::NowTicks`] it is NOT the frame-quantized game clock and keeps
     * advancing even while Automation-gated. `0` when detached.
     */
    ActualTicks: number;
    /**
     * Game-clock "now", in MILLISECONDS (fractional). Time-base: the game clock, which advances once
     * per game REFRESH; frozen from the script's view while Automation-gated (Automation off / window background) —
     * the gated tick is skipped, so a script re-observes the same value across gated ticks. This is
     * the same time-base the rule engine uses for cooldowns / `SinceLastActivation`, which likewise
     * only advance on ticks that actually run. `0.0` when detached.
     */
    NowMs: number;
    /**
     * Alias of [`Self::NowMs`] — the current game-clock time in MILLISECONDS. Same time-base and
     * same Automation-gated freeze behavior.
     */
    CurrentTickMs: number;
    /**
     * The most recent frame delta, in MILLISECONDS (fractional). Time-base: game clock; a gated tick
     * contributes no observable delta to a script (the tick is skipped). `0.0` when detached.
     */
    DeltaMs: number;
    /**
     * Convert a game-clock TICK count (100 ns units) to MILLISECONDS (fractional). Pure conversion —
     * no live clock read, so unaffected by Automation gating. `0.0` when detached.
     */
    ToMs(ticks: number): number;
    /**
     * ACTUAL wall-clock milliseconds elapsed since `sinceTicks` (a value from [`Self::ActualTicks`]),
     * in MILLISECONDS (fractional). Time-base: the underlying stopwatch, so — unlike the game-clock
     * members — it keeps measuring real time even while Automation-gated. `0.0` when detached.
     */
    ActualElapsedMs(sinceTicks: number): number;
  }

  interface Poe2CurrentAreaInfo {
    Name: string | null;
    IsTown: boolean;
    IsHideout: boolean;
    /**
     * Whether this resolved area is a town or hideout; does not indicate whether combat is occurring.
     * @keywords area, peaceful, town, hideout, combat
     */
    IsPeaceful: boolean;
  }

  interface Poe2DialogOption {
    Element: Element;
    TextType: DialogTextType;
    Text: string;
  }

  /**
   * A live UI-tree node. Its generated value handle is intentionally transient: an old tick's
   * handle resolves to no receiver and every `native_default` member degrades to its documented
   * empty/null value instead of reading stale process memory.
   */
  interface Element {
    Address: number;
    IsVisible: boolean;
    IsVisibleLocal: boolean;
    ChildCount: number;
    Text: string;
    TextNoTags: string;
    Children: Element[];
    GetChildAtIndex(index: number): Element | null;
    GetChildFromIndices(...indices: number[]): Element | null;
    ClientRect: RectangleF | null;
  }

  interface Poe2EntitiesAccessor {
    Player: Entity | null;
    Count: number;
    /**
     * Whether the entity manager published a complete snapshot for the current game frame.
     */
    IsCurrent: boolean;
    /**
     * The complete current-frame entity set. `Some(empty)` is known empty; `None` is unavailable
     * or incomplete. Filtering remains ordinary script code.
     */
    Current: EntityList | null;
    /**
     * Enumerate entities without an implicit count limit. Pass a limit only when partial results are intended.
     * @keywords entities, enumerate, complete, limit
     */
    All(limit?: number | null): EntityList;
    /**
     * Find alive, hostile, non-hidden monsters within the grid radius, filtered by rarity.
     * The default radius is 200 grid units; combine MonsterRarity flags with |. Use Take to limit the result count.
     * @keywords monsters, enemies, radius, rarity, reagent
     */
    Monsters(range?: number | null, rarity?: MonsterRarity | number | null): EntityList;
    Players(range?: number | null, limit?: number | null): EntityList;
    TryGetById(id: number): Entity | null;
    PlayerByName(name: string): Entity | null;
    PlayerByNameContains(text: string): Entity | null;
  }

  /**
   * A live entity handle. The generated value-handle contract owns JS identity and stale-handle
   * recovery; this facade owns only typed reads over the currently resolved Rust entity.
   */
  interface Entity {
    IsValid: boolean;
    /**
     * NPC overhead marker: a reason to talk, not proof that a reward is available.
     * Null for non-NPC entities, unreadable memory, or an unavailable handle.
     */
    HasIconOverhead: boolean | null;
    /**
     * Item content usable for reward/backpack comparisons; not a unique instance ID.
     */
    ItemKind: ItemKind | null;
    ItemBase: Poe2ItemBase | null;
    ItemMods: Poe2ItemMods | null;
    ItemStack: Poe2ItemStack | null;
    Id: number;
    Address: number;
    Type: string;
    TryType: string | null;
    Role: string;
    Path: string;
    Metadata: string;
    /**
     * The player's chosen character name, separate from CharacterClass.Name and Ascendancy.Name.
     * @keywords character, player, name, identity
     */
    PlayerName: string;
    IsAlive: boolean;
    /**
     * Current class and selected ascendancy, or null when the component or required records are unavailable.
     * Ascendancy is null only when the character is known to have none selected. Compare Id with
     * CharacterClass or Ascendancy constants; Name is display text. Read inside conditions to refresh.
     * @keywords character, class, ascendancy, build, condition, specialization
     */
    readonly CharacterClass: CharacterClassInfo | null;
    TryIsAlive: boolean | null;
    IsTargetable: boolean;
    TryIsTargetable: boolean | null;
    /**
     * Hostility as authored by the entity reaction state. A contended/stale row is unknown.
     */
    IsHostile: boolean | null;
    WorldPosition: Vector3;
    GridPosition: Vector2;
    TryGridPosition: Vector2 | null;
    /**
     * Grid-space distance to the player, matching query radii and EC2 DistancePlayer.
     * Returns null when the entity or player cannot be resolved.
     * @keywords distance, grid, radius, player, reagent
     */
    Distance: number | null;
    /**
     * World-space three-dimensional distance to the player. Query radii use grid units instead.
     * Returns null when either position is unavailable.
     * @keywords distance, world, position, player
     */
    WorldDistance: number | null;
    /**
     * Whether the terrain targeting layer has a clear straight line between the player and this
     * entity: walls block it, ledges do not. Doors follow the terrain refresh after they open or
     * close; skill-created walls are not included. Returns null when terrain or a position is unavailable.
     * @keywords line of sight, visibility, obstacle, wall, targeting
     */
    HasLineOfSight: boolean | null;
    Position: Vector3;
    IsDead: boolean;
    IsTargeted: boolean;
    /**
     * Whether the entity's current action has started; walking alone does not set it, casting on the move
     * does. `null` when this frame has no Actor snapshot of it, including entities without an Actor.
     * @keywords casting, attacking, action, busy
     */
    IsUsingAbility: boolean | null;
    IsInvincible: boolean;
    Scale: number;
    distance(target?: Entity | Poe2EntityPositionTarget | Vector3 | null): number | null;
    distanceTo(target: Entity | Poe2EntityPositionTarget | Vector3): number | null;
    direction(target?: Entity | Poe2EntityPositionTarget | Vector3 | null): Vector3 | null;
    directionTo(target: Entity | Poe2EntityPositionTarget | Vector3): Vector3 | null;
    angle(target?: Entity | Poe2EntityPositionTarget | Vector3 | null): number | null;
    angleTo(target: Entity | Poe2EntityPositionTarget | Vector3): number | null;
    Vitals: VitalsInfo;
    HP: Vital;
    ES: Vital;
    Mana: Vital;
    Ward: Vital;
    Rarity: MonsterRarity;
    /**
     * Fresh neutral rarity, or `None` when the row/component fact is unavailable.
     */
    TryRarity: MonsterRarity | null;
    /**
     * Live buffs of this entity. AllBuffs preserves every readable instance, including duplicate names.
     * @keywords entities, buffs, debuffs, duplicates
     */
    Buffs: Poe2BuffsAccessor;
    /**
     * Skills owned by this entity, using the same lookup and result contract as player Skills.
     * @keywords entities, skills, abilities, lookup
     */
    Skills: Poe2SkillsAccessor;
    Stats: { [id: string]: Stat } & { Has(id: string): boolean };
    States: { [id: string]: Stat } & { Has(id: string): boolean };
    Actor: ActorInfo;
    BaseEntityPath: string | null;
    AttachedAnimatedObjects: EntityInfo[];
    Position2D: Vector2;
    DistanceToCursor: number;
    VectorToCursor: Vector2;
    VectorToPlayer: Vector2;
    AngleToCursor: number;
    DistanceToCursorAngle: number;
  }

  /**
   * A typed target accepted by `Entity.distanceTo`, `directionTo`, and `angleTo`.
   */
  interface Poe2EntityPositionTarget {
    WorldPosition?: Vector3 | null;
  }

  /**
   * A belt-slot value stored directly in the generated native script object.
   */
  interface Poe2FlaskAccessor {
    Index: number;
    Slot: number;
    /**
     * The default belt-slot key label for this flask (`"D1"`..`"D5"`), or null out of range.
     */
    Hotkey: string | null;
    HasItem: boolean;
    /**
     * Whether this slot is empty or its charge state and local charge-use modifiers are readable.
     * @keywords flask, charm, availability, charges
     */
    IsAvailable: boolean;
    IsActive: boolean;
    Active: boolean;
    Name: string;
    BaseName: string;
    UniqueName: string;
    ClassName: string;
    /**
     * Whether current charges cover the item's locally modified cost; false when empty or unreadable.
     * This charge threshold does not check global character modifiers or other activation conditions.
     * @keywords flask, charm, readiness, charges, threshold
     */
    CanBeUsed: boolean;
    Charges: number;
    MaxCharges: number;
    /**
     * Charge cost after the item's local increased/reduced charges-used modifiers, rounded down.
     * Excludes global character modifiers. Returns 1 when empty or unreadable; check IsAvailable and HasItem.
     * @keywords flask, charm, cost, charges, reduction, rounding
     */
    ChargesPerUse: number;
    CanBeUsedIn: number;
    ChargePercent: number;
    MatchesName(text: string): boolean;
    /**
     * Queue this slot's default key through script-owned input. True means queued, not recovery confirmed.
     * Rebound game keys are not resolved; unavailable input returns false.
     * @keywords flask, charm, input, queue, ownership
     */
    Use(): boolean;
  }

  type Poe2FlasksAccessor = {
    Flask1: Poe2FlaskAccessor;
    Flask2: Poe2FlaskAccessor;
    Charm1: Poe2FlaskAccessor;
    Charm2: Poe2FlaskAccessor;
    Charm3: Poe2FlaskAccessor;
    Count: number;
    Hotkey(index: number): string | null;
    KeyName(index: number): string | null;
    IsAvailable: boolean;
    HasItemAt(index: number): boolean;
    ByIndex(index: number): Poe2FlaskAccessor | null;
    BySlot(slot: number): Poe2FlaskAccessor | null;
    All: Poe2FlaskAccessor[];
    ByName(name: string): Poe2FlaskAccessor | null;
    ByNameContains(text: string): Poe2FlaskAccessor | null;
    FindByNameContains(text: string, limit?: number | null): Poe2FlaskAccessor[];
    IsActive(index: number): boolean;
    /**
     * Returns the live server inventory slot for one flask. BindGen transports the facade as a
     * transient value handle and owns every JavaScript member binding.
     */
    TryGetItem(index: number): ServerInventorySlotItem | null;
    /**
     * Script projection of the belt-slot rectangle. The native `RectangleF` form remains for
     * Rust UI consumers; BindGen owns the structural JS encoding.
     * @requiresFeature PoE.Follow
     */
    TryGetSlotClientRect(index: number): RectangleF | null;
    /**
     * Read a zero-based belt slot, also available as Flasks[index]. Slots 0/1 are life/mana; 2–4 are charms.
     * Out-of-range indices throw. An empty or unavailable slot still provides its normal status handle.
     * @keywords flasks, charms, belt, indexer, reagent
     */
    Item(index: number): Poe2FlaskAccessor;
    /**
     * Queue the default belt key D1–D5 for a zero-based slot through script-owned input.
     * Returns false for an invalid slot or unavailable input. True means queued, not recovery confirmed.
     * Rebound game keys are not resolved.
     * @keywords flask, charm, input, queue, ownership
     */
    Use(index: number): boolean;
  } & { readonly [key: number]: Poe2FlaskAccessor };

  /**
   * Settings observed in the attached game process.
   * @keywords game, settings, configuration
   */
  interface Poe2GameConfigAccessor {
    /**
     * Active game input settings, independent of foreground focus.
     * @keywords game, bindings, keyboard, configuration
     */
    Input: Poe2GameInputConfigAccessor;
  }

  /**
   * Input bindings for the game's current supported control mode.
   * @keywords game, settings, input, bindings
   */
  interface Poe2GameInputConfigAccessor {
    /**
     * Whether the current input settings were read successfully in a supported mode.
     * Mouse/keyboard and WASD are supported; controller, a closed session or failed reads return false.
     * This reports config availability, not skill-bar/UI readiness, and does not require foreground focus.
     * @keywords input, bindings, availability, mode
     */
    IsAvailable: boolean;
    /**
     * Read an action's actual key/chord, for example "use_bound_skill5".
     * Null means unbound or unavailable (check IsAvailable); an unknown action in an available table throws.
     * Unsupported native key/modifier values also throw. This reads a setting, does not rebind it or resolve a SkillInfo.
     * @example
     * ```ts
     * if (World.GameConfig.Input.IsAvailable) {
     *   Log(World.GameConfig.Input.GetHotkey("use_bound_skill5") ?? "Unbound action");
     * }
     * ```
     * @see World.SkillBar.ByHotkey
     * @keywords game, bindings, action, hotkey, settings
     */
    GetHotkey(action: string): string | null;
  }

  interface Poe2GroundItemInfo {
    /**
     * The live in-game item entity (rarity, components, world position) — the real object a script
     * should read, not a snapshot. `EntityId`/`EntityAddress`/`EntityPath` stay as denormalized
     * convenience scalars.
     */
    Entity?: Entity | null;
    EntityId: number;
    EntityPath: string;
    LabelText: string;
    Name: string;
    IsLootable: boolean;
    IsVisible: boolean;
    CanPickUp: boolean;
    ClientX: number;
    ClientY: number;
    ClientWidth: number;
    ClientHeight: number;
    /**
     * JavaScript numbers retain the established script contract for pointer-like diagnostic values.
     */
    EntityAddress: number;
    /**
     * JavaScript numbers retain the established script contract for pointer-like diagnostic values.
     */
    LabelAddress: number;
    ClientCenterX: number;
    ClientCenterY: number;
    MatchesName(text: string): boolean;
    /**
     * The item's live world position, or `None` when the backing entity wrapper is contended —
     * Option-shaped exactly like [`Poe2PartyMemberAccessor::WorldPosition`], so a miss reads as
     * "position unavailable" instead of a garbage `Vec3::ZERO` (distance-to-origin).
     */
    WorldPosition: Vector3 | null;
    distance(position?: Vector3 | null): number | null;
    distanceTo(position: Vector3): number | null;
    direction(position?: Vector3 | null): Vector3 | null;
    directionTo(position: Vector3): Vector3 | null;
    angle(position?: Vector3 | null): number | null;
    angleTo(position: Vector3): number | null;
  }

  /**
   * Live state for one typed hotkey gesture. Clones share one coordinator subscription; dropping
   * or stopping the last handle releases its physical registration.
   */
  interface Poe2HotkeyObservation {
    /**
     * False until the coordinator has delivered the first physical baseline, and after Stop.
     */
    IsAvailable: boolean;
    /**
     * Current physical state, or null before the first baseline / after Stop.
     */
    IsDown: boolean | null;
    /**
     * Stops the observation and releases its physical subscription.
     * @keywords hotkey, observation, subscription, cleanup
     */
    Stop(): void;
  }

  /**
   * Direct keyboard and mouse input without an HTN task.
   * Commands return no completion promise; use `task.Input` for awaitable task actions.
   */
  interface Poe2InputAccessor {
    InputSimulatorLabel: string;
    InputSmootherLabel: string;
    CursorScreenPosition: Vector2;
    CursorClientPosition: Vector2;
    /**
     * Observe a full gesture through the shared product hotkey coordinator. Returns null when
     * observation hosting is unavailable; the returned handle owns and cleans up its subscription.
     */
    ObserveHotkey(gesture: Key | string): Poe2HotkeyObservation | null;
    /**
     * Accepts both generated `Key` values and string aliases (for example `"esc"`).
     */
    IsKeyDown(key: Key | string): boolean;
    /**
     * Queues a direct key press without creating a task. Returns before input completion;
     * `await` does not wait for this command. Use `task.Input.KeyPress` for a task action.
     * Execution follows the automation input gates.
     * @param keyPressDelay Hold duration in milliseconds; omitted uses the host default. Negative values throw.
     * @keywords input, key, press, duration, milliseconds
     */
    KeyPress(key: Key | string, keyPressDelay?: number | null): void;
    KeyDown(key: Key | string): void;
    KeyUp(key: Key | string): void;
    /**
     * Releases keyboard keys tracked as held by direct script input; does not cancel HTN tasks.
     * Panic-safe when Automation is gated. Use MouseUp for directly held mouse buttons.
     */
    ReleaseAll(): void;
    MouseMoveToClient(clientPosition: Vector2): void;
    MouseMoveToClientXY(x: number, y: number): void;
    MouseLeftClickClient(clientPosition: Vector2, clickDelayMs?: number | null): void;
    MouseLeftClickClientXY(x: number, y: number, clickDelayMs?: number | null): void;
    MouseDown(button?: MouseButton | null): void;
    MouseUp(button?: MouseButton | null): void;
  }

  /**
   * Player backpack status and actions. The backing model is the canonical server inventory plus the
   * native inventory UI panel; this type only chooses the player backpack and provides one-action
   * interactions.
   */
  interface Poe2InventoryAccessor {
    /**
     * True when the server-side player backpack is readable.
     */
    IsAvailable: boolean;
    /**
     * False when backpack enumeration retained an older snapshot after a read fault.
     */
    HasFreshBackpack: boolean;
    /**
     * True when the inventory window and player backpack panel are visible.
     * @requiresFeature PoE.Follow
     */
    IsOpen: boolean;
    /**
     * True when the player backpack is readable and visible enough for item clicks.
     * @requiresFeature PoE.Follow
     */
    CanClickItems: boolean;
    /**
     * Returns whether a server item occupies the requested backpack cell.
     */
    HasItemAt(x: number, y: number): boolean;
    /**
     * Script projection of the backpack rectangle. The native `RectangleF` form remains for
     * Rust UI consumers; BindGen owns the structural JS encoding.
     * @requiresFeature PoE.Follow
     */
    TryGetBackpackClientRect: RectangleF | null;
    /**
     * Number of backpack grid columns (server inventory `Columns`), or 0 when the backpack is unreadable.
     */
    Columns: number;
    /**
     * Number of backpack grid rows (server inventory `Rows`), or 0 when the backpack is unreadable.
     */
    Rows: number;
    /**
     * Number of items in the player backpack (server inventory `ItemCount`), or 0 when unreadable.
     */
    ItemCount: number;
    /**
     * Live snapshot of the player backpack items as plain data. Facade-level equivalent of iterating the
     * C# `Inventory.Backpack` server inventory; non-clickable/placeholder slots are skipped.
     */
    Items: Poe2BackpackItemInfo[];
    /**
     * Left-clicks a random point inside the item occupying the requested backpack cell.
     * @keywords inventory, backpack, item, click
     * @requiresFeature PoE.Follow
     */
    TryClickItemAt(x: number, y: number): boolean;
    /**
     * Ctrl-left-clicks a random point inside the item occupying the requested backpack cell.
     * @keywords inventory, backpack, control, click
     * @requiresFeature PoE.Follow
     */
    TryCtrlClickItemAt(x: number, y: number): boolean;
    /**
     * Left-clicks a random point inside the item occupying the requested backpack cell.
     * @keywords inventory, backpack, modifiers, click
     * @requiresFeature PoE.Follow
     */
    TryClickItemAtWithModifiers(x: number, y: number, control: boolean, shift: boolean): boolean;
  }

